/* Lot 92: linear-gradient angles in radians, written back as whole degrees (generated by scripts/lot92_bggen.py; expectations from that model). */

#include "../../framework/unity.h"
#include <string.h>
#include "wf_cssbg.h"

static char g_o[WF_CSSBG_VAL];

static const char *run(const char *f, const char *v) {
    int r;
    if (!strcmp(f, "img")) r = wf_cssbg_image(v, g_o, (int)sizeof(g_o));
    else r = wf_cssbg_gradient(v, (int)strlen(v), g_o, (int)sizeof(g_o));
    if (r <= 0) return g_o[0] ? "REFUSED BUT WRITTEN" : "REFUSED";
    if (r != (int)strlen(g_o)) return "BAD LENGTH";
    return g_o;
}

static void test_l92_rad_0(void) {
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "linear-gradient( 58.1440rad, rgb(246, 172, 246), #3f74c1, teal, rgb(152, 145, 225) )"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "LINEAR-GRADIENT( -44.0rad,\trgb(25, 165, 126),\trgb(31, 46, 183),\t#b41,\tgray )"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "linear-gradient(-3.15138rad, lime, rgb(23, 237, 8)  )"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "LINEAR-GRADIENT(  -40.84070rad, white 21%, gray\t)"));
    TEST_ASSERT_EQUAL_STRING("REFUSED", run("grad", "LINEAR-GRADIENT(\t58RAD,#85a10f,green 90%)"));
    TEST_ASSERT_EQUAL_STRING("linear-gradient(-720deg, green 57%, navy)", run("grad", "linear-gradient( -12.5664rad,  green 57%,  navy )"));
}

